// 2. 从低位到高位逐位相加 (循环条件是更大的位数), 得到加法与进位.
// 3. 处理边界条件: 相加时位数增加.
#include <iostream>
#include <cstdio>
#include <string>
#include <cmath>
using namespace std;
int a[510], b[510], c[510];
int main() {
    string A, B;
    getline(cin, A);
    getline(cin, B);
    int size = max(A.size(), B.size());
    // 写入数组时第一次逆序
    // i指向写入数组的位置, j指向原字符串的位置
    for (int i = 1, j = A.size() - 1; j >= 0; i++, j--) {
        a[i] = A[j] - '0';
    }
    for (int i = 1, j = B.size() - 1; j >= 0; i++, j--) {
        b[i] = B[j] - '0';
    }

    // 相加, 处理进位, 并考虑size增加的情况
    for (int i = 1; i <= size; i++) {
        c[i + 1] += (c[i] + a[i] + b[i]) / 10;
        c[i] = (c[i] + a[i] + b[i]) % 10;
    }
    if (c[size + 1]) size++;

    // 最后输出时第二次逆序
    for (int i = size; i >= 1; i--) {
        cout << c[i];
    }
    cout << endl;
    return 0;
} 乘积位数不会超过两数的位数之和。
注意“贡献”（包括乘、进位） 有重叠是 += ，而“保留个位”是 = 。 #include <iostream>
#include <cstdio>
#include <string>
#include <cmath>
using namespace std;
int a[2010], b[2010], c[4010];
int main() {
    // 1. 读入并逆序.
    string A, B;
    cin >> A >> B;
    for (int i = 1, j = A.size() - 1; j >= 0; i++, j--) {
        a[i] = A[j] - '0';
    }
    for (int i = 1, j = B.size() - 1; j >= 0; i++, j--) {
        b[i] = B[j] - '0';
    }

    // 首先处理乘法, 将b[j]这一位与向量a相乘, 得到对c的向量贡献
    for (int j = 1; j <= B.size(); j++) {
        for (int i = 1; i <= A.size(); i++) {
            c[i + j - 1] += b[j] * a[i]; // 注意有重叠, 需要用+=
        }
    }
    // 再处理进位
    int sz = A.size() + B.size(); // 上界
    for (int i = 1; i <= sz; i++) {
        c[i + 1] += c[i] / 10;
        c[i] = c[i] % 10;
    }

    // 3. 读出并逆序.
    while (c[sz] == 0) sz--; // 去掉前导零, 引入特判: 要小心位数变为0的情况
    for (int i = max(sz, 1); i >= 1; i--) {
        cout << c[i];
    }
    cout << endl;
    return 0;
