在 operator[] 的实现中，为了能够像数组那样直接修改某一位的值， 需要返回该位的引用 int& ，而不是拷贝 int 。） #include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>
using namespace std;
// 这里的位数maxn是怎么估算出来的呢?
// 50!, 每两个数都是2位, 它们的乘积不超过4位.
// 50个数依次相乘, 从而乘积位数不会超过100位.
#define maxn 100
struct Bigint {
    int len = 0, a[maxn];
    Bigint(int x = 0) { // 初始值构造函数, 初始化传入的大小不超过int
        memset(a, 0, sizeof(a)); // <cstring>
        for (int i = 1; x; i++) {
            a[i] = x % 10; // 第一次逆序写入
            x /= 10;
            len++;
        }
    }

    int &operator[](int i) {
        return a[i];
    }

    void flatten(int L) {
        // 处理1-L这一段的进位 (L以上截断), 并去掉前导0.
        len = L;
        for (int i = 1; i <= len; i++) {
            a[i + 1] += a[i] / 10;
            a[i] %= 10;
        }
        while (!a[len]) len--;
    }

    void print() {
        for (int i = max(len, 1); i >= 1; i--) {
            printf("%d", a[i]);
        }
    }
};

Bigint operator+(Bigint a, Bigint b) {
    Bigint c;
    int len = max(a.len, b.len);
    for (int i = 1; i <= len; i++) {
        c[i] += a[i] + b[i];
    }
    c.flatten(len + 1);
    return c;
}

Bigint operator*(Bigint a, int b) { // 简便起见, Bigint乘int
    Bigint c;
    int len = a.len;
    for (int i = 1; i <= len; i++) {
        c[i] = a[i] * b;
    }
    c.flatten(len + 11); // int<=2147483647即10位
    return c;
}

int main() {
    Bigint ans(0), fac(1);
    int m;
    cin >> m;
    for (int i = 1; i <= m; i++) {
        fac = fac * i; // 注意你定义的是*不是*=, 不要乱写(?
        ans = ans + fac;
    }
    ans.print();
    return 0;
