} 选择排序、冒泡排序、插入排序。 // 选择排序:
// 每次选中最小的元素, 将其置于已排序段的末尾.
// 已排序段初始长度为0, 指针指向位置0.
for (int i = 0; i < n; i++) {
    // 找到最小的元素, 将其与"空位"a[i]交换.
    int maxi = i, maxval = a[i];
    for (int j = i + 1; j < n; i++) {
        if (a[j] < maxval) {
            maxi = j;
            maxval = a[j];
        }
    }
    swap(a[i], a[maxi]);
} // 选择排序的第二种写法.
// 遍历时, 如果相应元素更小, 则将它交换到指定为止.
for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
        if (a[j] < a[i]) swap(a[j], a[i]);
    }
} // 冒泡排序.
// 每次冒泡是从前到后的交换链, 冒泡完后保证当前最大元素交换到最后.
for (int i = 0; i < n - 1; i++) {
    for (int j = 0; j < n - i - 1; j++) { // 下标边界: 来自对a[j]和"a[j+1]"的比较
        if (a[j] > a[j + 1]) swap(a[j], a[j + 1]);
    }
} // 插入排序.
// 腾出空位, 将新的元素插入已排序的序列中.
for (int i = 1; i < n; i++) { // 初始a[0]已有序
    int x = a[i], j = i - 1;
    for (; j >= 0; j--) {
        if (a[j] <= x) break;
        a[j + 1] = a[j];
    }
    a[j + 1] = x;
} （重点：快速排序的剪枝板子） // 快速排序板子.
// 划分 + 自顶向下分治.
// 这个板子的好处是可以剪枝, 常数优化好一些,
// 而且整个代码结构超级无敌对称, 不需要一边置为<=、一边置为>。
#include <iostream>
#include <cstdio>
using namespace std;
const int MAXN = 100010;
int a[MAXN], n;

void quicksort(int l, int r) {
    int i = l, j = r, x = a[(l + r) / 2];
    do {
        // 左边找>=的, 右边找<=的, 交换.
        while (a[i] < x) i++;
        while (a[j] > x) j--;
        if (i <= j) {
            swap(a[i], a[j]);
            i++; j--;
        }
    } while (i <= j);
    // 跳出时, i > j,
    // 如果是 l j i r的关系, 则继续排[l,j]和[i,r]
    if (l < j) quicksort(l, j);
    if (i < r) quicksort(i, r);
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    quicksort(0, n - 1);
    for (int i = 0; i < n; i++) {
        cout << a[i] << ' ';
    }
    cout << endl;
    return 0;
} 备注：注意这里 MAXN = 5e6 ，已经很大了，读入数字请用 scanf 而非 cin ，要不然会卡常（用例5搞出1.2s左右）。 // 思想:
// 看k属于的区间.
// 每次划分后, [l, j], [j + 1, i - 1], [i, r] 三个区间相对大小有序.
// k属于其中一个区间, 通过与下标的大小关系确定.
#include <iostream>
#include <cstdio>
using namespace std;
const int MAXN = 5000010;
int a[MAXN];
int ans = 0, k;
void findkth(int l, int r) {
    if (l == r) {
        ans = a[l];
        return;
    }

    int i = l, j = r, x = a[(l + r) / 2];
    do {
        // 左边找大的, 右边找小的
        while (a[i] < x) i++;
        while (a[j] > x) j--;
        if (i <= j) {
            swap(a[i], a[j]);
            i++; j--;
        }
    } while (i <= j);

    // 跳出条件有所区别, [l, j], [i, r]
    if (k <= j) findkth(l, j); // 在[l, j]区间
    else if (i <= k) findkth(i, r); // 在[i, r]区间
    else findkth(j + 1, i - 1); // j < k < i, 在[j + 1, i - 1]区间
}

int main() {
    int n;
    cin >> n >> k;
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    findkth(0, n - 1);
    cout << ans << endl;
    return 0;
} （解一）范围小，所以用计数排序。 #include <iostream>
