count[N] = count[N - 1] + count[N - 2]
count[1] = 1
count[2] = 2 这个递推很显然在 \(a^n\) 的数量级，因此需要高精度。 首先， \(count[n] \le 2^n\) 是显然的。粗略估算， \(2^{10} \approx 10^3\) ，那么 \(2^{5000} \approx 10^{1500}\) 。保险起见高精度内的数组开个1600位什么的就足够了。 #include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>
using namespace std;
#define maxn 1600
struct Bigint {
    int len = 0, a[maxn];
    Bigint(int x = 0) { // 初始值构造函数, 初始化传入的大小不超过int
        memset(a, 0, sizeof(a)); // <cstring>
        for (int i = 1; x; i++) {
            a[i] = x % 10; // 第一次逆序写入
            x /= 10;
            len++;
        }
    }

    int &operator[](int i) {
        return a[i];
    }

    void flatten(int L) {
        // 处理1-L这一段的进位 (L以上截断), 并去掉前导0.
        len = L;
        for (int i = 1; i <= len; i++) {
            a[i + 1] += a[i] / 10;
            a[i] %= 10;
        }
        while (!a[len]) len--;
    }

    void print() {
        for (int i = max(len, 1); i >= 1; i--) {
            printf("%d", a[i]);
        }
    }
};

Bigint operator+(Bigint a, Bigint b) {
    Bigint c;
    int len = max(a.len, b.len);
    for (int i = 1; i <= len; i++) {
        c[i] += a[i] + b[i];
    }
    c.flatten(len + 1);
    return c;
}

Bigint operator*(Bigint a, int b) { // 简便起见, Bigint乘int
    Bigint c;
    int len = a.len;
    for (int i = 1; i <= len; i++) {
        c[i] = a[i] * b;
    }
    c.flatten(len + 11); // int<=2147483647即10位
    return c;
}

int main() {
    int n;
    cin >> n;
    Bigint count[5010];
    count[1] = 1;
    count[2] = 2;
    for (int i = 3; i <= n; i++) {
        count[i] = count[i - 1] + count[i - 2];
    }
    count[n].print();
    return 0;
