        cin >> a >> b >> c;
        if (a == -1 && b == -1 && c == -1) {
            break;
        } else {
            printf("w(%lld, %lld, %lld) = %lld\n", a, b, c, w(a, b, c));
        }
    }
    return 0;
} 由简到繁思考。 （不含递归）对于 [4CB] ，逐个字符读取。读到 [ 时，读入这一段的数字，直到读到字母；然后读入字母，直到读到 ] ，将字母转成字母的重复。 （包含递归）对于 [2[2CB]] ，读到 [ 时，读入这一段的数字，直到读到 [ ，则一直往后读，直到读到 ] ，对这一段调用函数，然后转成子问题结果的重复。
总而言之，我们的函数解释为将一段字符串展开。如果遇到递归，则对递归段调用函数，从而转化回将一段字符串展开的问题，然后再展开。 举个例子：
调用函数 expand("[2[2CB]]") 。
首先读入 [ 和数字 2 ，然后发现又有 [ ，需要先对后面一整段调用子函数，即 expand([2CB]]) ，调用后子函数将这一段展开为 CBCB] ，则字符串变为 [2CBCB] ，再同理展开即可。 #include <iostream>
#include <string>
using namespace std;
string expand() {
    string s = "", X;
    char c;
    int D;
    while (cin >> c) {
        if (c == '[') {
            cin >> D;
            X = expand();
            while (D--) s += X;
        } else if (c == ']') {
            return s;
        } else {
            s += c;
        }
    }
    return s;
}

