这个不是01背包（战略放弃可能得到更多），而是分数背包，贪心是最优的。 贪心证明：copy-and-paste。假设最优解某次在背包中放入了价值低的金币，则可以将这个金币替换为贪心的价值高的金币，价值不会降低。如是循环，直到最优解全部替换为贪心解，价值不会降低，所以贪心解为最优解。 #include <iostream>
#include <cstdio>
#include <algorithm>
using namespace std;
int n, T;
struct coin {
    int m, v; // 总重量, 总价值
} coins[110];

bool cmp(coin a, coin b) {
    // a.v / a.m > b.v / b.m
    return a.v * b.m > a.m * b.v;
}

float greedy() {
    int remain = T;
    float res = 0; // 剩余空间, 已装价值
    int i;
    for (i = 0; i < n; i++) {
        auto coin = coins[i];
        if (coin.m > remain) break;
        // 想不通就获取信息, 不要硬盯着代码看
        //printf("remain: %d, coin.m: %d, coin.v: %d\n", remain, coin.m, coin.v);
        res += coin.v;
        remain -= coin.m;
    }
    // 允许分割
    if (i < n) res += 1.0 * remain * coins[i].v / coins[i].m;
    return res;
}

int main() {
    cin >> n >> T;
    for (int i = 0; i < n; i++) {
        cin >> coins[i].m >> coins[i].v;
    }
    sort(coins, coins + n, cmp);
    printf("%.2f\n", greedy());
    return 0;
} 对于等待问题，画图出来会特别清晰。 等待总时长 \[s=(n-1)t_1+(n-2)t_2 + \dots + 1 \cdot t_{n-1} + 0 \cdot t_n\] 贪心策略：前面的时间段系数大、后面的小。从而应当让接水时间较短的人先接。
贪心证明：调度类的问题使用交换论证。贪心得到的应该是接水时间的升序序列。反设最优解中有两者逆序（ \(t_i>t_j\) 但 \(i < j\) ，则由前述可知系数 \(a>b\) ），它们对等待总时长的贡献为 \(at_i+bt_j\) 。将这两者交换后，贡献变为 \(at_j+bt_i\) 。
后者减前者得到 \(a(t_j-t_i)+b(t_i-t_j)=(a-b)(t_j-t_i)<0\) ，即交换后贡献的等待时长更少，矛盾。 另外需要估算结果大小： \(n \le 1000\) ， \(t_i \le 10^6\) ，则最大情况下是 \((999 + 998 + \dots + 1) \times 10^6 = 999/2 \times 10^9 \approx 5 \times 10^{11}\) ，这铁定是不能用 int （ \(2 \times 10^9\) ）了。 #include <iostream>
#include <cstdio>
#include <algorithm>
using namespace std;
struct person {
    int id, time;
} p[1010];

// 按照time, id升序
bool cmp(person a, person b) {
    if (a.time != b.time) {
        return a.time < b.time;
    } else {
        return a.id < b.id;
    }
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        p[i].id = i + 1;
        cin >> p[i].time;
    }
    sort(p, p + n, cmp);
    // 排队顺序
    for (int i = 0; i < n; i++) {
        cout << p[i].id << ' ';
    }
    cout << endl;

    // 平均等待时间
    long long total = 0;
    for (int i = 0; i < n; i++) {
        total += (n - 1 - i) * p[i].time;
    }
    printf("%.2f\n", 1.0 * total / n);
    return 0;
} 结束时间越早，能够留给其他比赛的剩余时间越多。
