    int i = 0, j = 0, w;
    for (int k = 1; k < n; k++) { // 合并n-1次
        w = a1[i] < a2[j] ? a1[i++] : a2[j++];
        w += a1[i] < a2[j] ? a1[i++] : a2[j++];
