int a[21]; // s[i] <= 20, 每一科不超过20道
int maxtime, curtime, sum, ans = 0, n;

void dfs(int x) { // 从第0道到第s[i] - 1道
    if (x >= n) { // 0~n-1题目计算curtime已处理完毕
        maxtime = max(maxtime, curtime);
        return;
    }
    // 确定当前下标x的题目是否加入子集
    if (curtime + a[x] <= sum / 2) {
        curtime += a[x];
        dfs(x + 1);
        curtime -= a[x];
    }
    // 注意下面这里不能写进else:
    // 如果满足条件, 则选择该题目和"不选择该题目"都要处理.
    // 如果不满足条件, 则只处理"不选择该题目".
    dfs(x + 1);
}

