    scanf("%d", &M);
    for (int i = 0; i < M; i++) {
        scanf("%d%d%d", &x, &y, &t);
        x += 1; y += 1; // 转成1~301, 便于边界处理
        for (int j = 0; j < 5; j++) { // 烧五个格子, 取最早
            if ((x + dx[j] >= 1) && (y + dy[j] >= 1)) {
                a[x + dx[j]][y + dy[j]] = min(t, a[x + dx[j]][y + dy[j]]);
            }
        }
    }
    bfs();
    return 0;
