struct node {
    int pre, nxt; 
    int key;
    node (int _k = 0, int _p = 0, int _n = 0) {
        pre = _p; nxt = _n; key = _k;
    }
}

node s[1005]; // 由序号到节点
int tot = 0; // total, 已使用的位置数量, 下一个可用的是 s[tot + 1]
// 链表起点是s[1]

int find(int x) {
    int now = 1;
    while (now && s[now].key != x) now = s[now].nxt;
}

// 把y插在x后面.
// 相当于: 根据值找到x的位置, 分配y (位置为++tot), 后插y
void ins_back(int x, int y) {
    int now = find(x);
    s[++tot] = node(y, now, s[now].nxt);
    s[s[now].nxt].pre = tot;
    s[now].nxt = tot;
}

// 把y插在x前面.
void ins_front(int x, int y) {
    int now = find(x);
    s[++tot] = node(y, s[now].pre, now);
    s[s[now].pre].nxt = tot;
    s[now].pre = tot;
}

// 值为x的节点的下一个节点的值为多少
int ask_back(int x) {
    int now = find(x);
    return s[s[now].nxt].key;
}

int ask_front(int x) {
    int now = find(x);
    return s[s[now].pre].key;
}

// ps. 似乎并不考虑回收空间, 
// 不然我感觉可以跟tot交换一下, 然后再tot--.
void del(int x) {
    int now = find(x);
    int pre = s[now].pre, nxt = s[now].nxt;
    s[pre].nxt = nxt;
    s[nxt].pre = pre;
} 以上是一个使用数组而非指针实现的双向链表。最好把 find 换成一个数组或者 unordered_map ，这样的话根据某个元素值找到它的节点就是 \(O(1)\) 的。不然每次都要 \(O(n)\) 遍历。 前后插、维护index数组都很平常，
