void play(int n) {
    // 把函数逻辑的调用放入循环里, 一开始只是处理stk的初始放入
    stack<int> stk; // 栈用于负责"函数调用的控制流".
    stk.push(n);

    while (!stk.empty()) {
        // 获取函数参数
        int current = stk.top(); stk.pop();
        // 函数逻辑
        ans += current;
        if (current == 1 || current == 2) continue;
        // 递归调用时先play(n-1)后play(n-2)
        // 所以栈调用应为先压入n-2后压入n-1
        stk.push(n - 2);
        stk.push(n - 1);
    }
