#include <stack>
using namespace std;

int ans = 0;

void play_stack(int n) {
    stack<int> st;

    // 初始调用
    st.push(n);

    while (!st.empty()) {
        int current = st.top();
        st.pop();

        // 相当于递归中的 ans += n
        ans += current;

        // 相当于递归中的终止条件检查
        if (current == 1 || current == 2) {
            continue;  // 不再继续展开
        }

        // 模拟递归调用：先 play(n-1)，后 play(n-2)
        // 因为栈是后进先出，所以要先压入 n-2，再压入 n-1
        st.push(current - 2);  // 第二调用
        st.push(current - 1);  // 第一调用
    }
}

