    // 原递归函数
    auto play_recursive = [](auto&& self, int n) -> void {
        ans += n;
        if (n == 1 || n == 2) return;
        self(self, n - 1);
        self(self, n - 2);
    };

    ans = 0;
    play_recursive(play_recursive, 5);
    cout << "play_recursive(5) = " << ans << endl;

    return 0;
} 二叉树专题 上图n=3，有8个国家参加，需要3轮比赛，高度为4。
