其中最关键的是： 路径压缩 。（查询降低至 \(O(\log n)\) ）
即 find 除了找到根，还要把一路上每一个节点的 fa 都设成根。 路径压缩的两种写法： int find(int x) {
    if (x == fa[x]) return x;
    return fa[x] = find(fa[x]);  // 递归+路径压缩
} #include <iostream>
#include <cstdio>
using namespace std;
int n, m, p, x, y;
int fa[MAXN];

// 路径压缩
int find(int x) {
    // 先找到根
    int root = x;
    while (root != fa[root]) {
        root = fa[root];
    }
    // 然后把一路上的fa都设成根
    // 注意为了防止丢失信息, 需要先拷贝再设置
    while (x != root) {
        int parent = fa[x];
        fa[x] = root;
        x = parent;
    }
    return root;
}

void join(int c1, int c2) {
    // 注意这里是find不是fa
    int f1 = find[c1], f2 = find[c2];
    if (f1 != f2) fa[f1] = f2;
}

int main() {
    cin >> n >> m >> p;
    for (int i = 1; i <= n; i++) fa[i] = i;
    for (int i = 0; i < m; i++) {
        cin >> x >> y;
        join(x, y);
    }
    for (int i = 0; i < p; i++) {
        cin >> x >> y;
        if (find(x) == find(y)) {
            cout << "Yes" << endl;
        } else {
            cout << "No" << endl;
        }
    }
    return 0;
} 相当于已有 w 个连通分支，将它们合并为 1 个连通分支需要多少次合并。
