这一块的迭代器真的很微妙： begin() 是闭的，而 end() 是开的，
导致你可以直接对 begin() 解引用、而 end() 不行，
除此之外当然不能对 begin() 进行 -- ，也不能对 end() 进行 ++ 。 #include <iostream>
#include <set>
using namespace std;
set<int> ds;
int main() {
    int n, opt, x;
    cin >> n;
    while (n--) {
        cin >> opt >> x;
        if (opt == 1) {
            if (ds.find(x) != ds.end()) {
                cout << "Already Exist" << endl;
            } else {
                ds.insert(x);
            }
        } else {
            if (ds.empty()) {
                cout << "Empty" << endl;
            } else if (ds.find(x) != ds.end()) {
                cout << x << endl;
                ds.erase(x);
            } else {
                // ds.lower_bound(x)是大于等于x的第一个元素
                // (区别于upper_bound: 大于的第一个元素)
                // 比较lower_bound和它前面的元素, 看哪个更接近x
                auto i = ds.lower_bound(x), j = i;
                if (j != ds.begin()) j--;
