对于被指的点，如点 y ，删去从 x 到 y 的边，并处理 x 对 y 的影响（如 f[y] = (f[x] + f[y]) % MOD ）。
如果 y 的入度变为0时，将它加回队列。 对于该题目，首先把所有极大值点的 f 值置为1。
对于每个中间点，它的 f 值等于所有指向它的点的 f 值之和。
因此只需要拓扑排序遍历所有点（初始点为所有极大值点），并填充 f ，最后遍历所有极小值点得到链的个数即可。 #include <iostream>
#include <cstring>
#include <vector>
#include <queue>
#define MAXN 5010
#define MAXM 500010
#define MOD 80112002
using namespace std;
int n, m, ans = 0;
vector<int> p[MAXN];
queue<int> q;
int f[MAXN], ind[MAXN], outd[MAXN];

int main() {
    cin >> n >> m;
    for (int i = 1; i <= m; i++) {
        int x, y;
        cin >> x >> y;
        outd[x]++;
        ind[y]++;
        p[x].push_back(y);
    }
    memset(f, 0, sizeof(f));
    // 1. 遍历所有极大值点, 初始化.
    for (int i = 1; i <= n; i++) {
        if (ind[i] == 0) { // 遍历所有极大值点
            f[i] = 1;
            q.push(i);
        }
    }
    // 2. 拓扑排序遍历所有非极大值点, 填表.
    while (!q.empty()) {
        int x = q.front(); q.pop();
        for (int i = 0; i < p[x].size(); i++) {
            // 删去一条边 (ind[y]--), 并处理x对y的影响
            int y = p[x][i];
            f[y] = (f[x] + f[y]) % MOD;
            ind[y]--;
            if (ind[y] == 0) q.push(y);
        }
    }
    // 3. 遍历所有极小值点, 统计链的总数.
    for (int i = 1; i <= n; i++) {
        if (outd[i] == 0) ans = (ans + f[i]) % MOD;
    }
    cout << ans << endl;
    return 0;
