10进制转n进制：从右往左“添加”，将已经有的数字取出offset（如16），然后剩下的数字除以进制（或者理解为“右移”），得到逆序。 #include <iostream>
#include <string>
using namespace std;

// 1-10,ABCDEF转成数字
int c2i(char a) { // char to int
    if ('0' <= a && a <= '9') return a - '0';
    else return 10 + a - 'A';
}

char i2c(int a) {
    // 这里写 0 <= a <= 9 不行, 原因不明
    if (a <= 9) return '0' + a;
    else return a - 10 + 'A';
}

int main() {
    int output[33]; // 最长的是二进制数, 根据题目含义不超过2147483647, 所以32"位"足够了
    int n, m, dec = 0, num = 0;
    string input;
    cin >> n >> input >> m;
    // n进制转换为10进制
    // eg. 3 * 16^2 + 2 *16^1 + 1
    // = 16 * (16 * (16 * 0 + 3) + 2) + 1
    // 相当于先乘以基数再加offset
    for (int i = 0; i < input.length(); i++) {
        dec = dec * n + c2i(input[i]);
    }
    // 10进制转换为m进制
    // 相当于先取offset再除以基数
    // 注意此时得到的是逆序的
    while (dec != 0) {
        output[num++] = dec % m;
        dec /= m;
    }
    for (int i = num - 1; i >= 0; i--) {
        cout << i2c(output[i]);
    }
    cout << endl;
    return 0;
} 计数原理与排列组合专题 选择最局限的兔子要先选，是因为如果其他兔子先选，可能出现选择最局限的兔子无牌可选的情况，该情况无解，使得相关的计算变复杂。
