    scanf("%d%d", &x, &y);
    for (int k = 1; k <= y / k; k++) {
        if (y % k == 0) {
            if (gcd(k, y / k * x) == x) cnt++;
            if (y / k != k) {
                if (gcd(y / k, k * x) == x) cnt++;
            }
        }
    }
    printf("%d", cnt);
    return 0;
} #include <cstdio>
using namespace std;
int gcd(int x, int y) {
    return y ? gcd(y, x % y) : x;
}
int lcm(int x, int y) {
    return x / gcd(x, y) * y;
}
int T, a0, a1, b0, b1;
int main() {
    scanf("%d", &T);
    while (T--) {
        int cnt = 0;
        scanf("%d%d%d%d", &a0, &a1, &b0, &b1);
        for (int x = 1; x <= b1 / x; x++) {
            if (b1 % x == 0) {
                if (gcd(x, a0) == a1 && lcm(x, b0) == b1) cnt++;
                if (b1 / x != x) {
                    if (gcd(b1 / x, a0) == a1 && lcm(b1 / x, b0) == b1) cnt++;
                }
            }
        }
        printf("%d\n", cnt);
    }
    return 0;
} #include <bits/stdc++.h>
using namespace std;
#define MAXN 10010
int m1, m2, n, pri[MAXN], tot[MAXN], a[MAXN];
int Decomposition(int x) {
    int cnt = 0, Cnt = 0;
    for (int i = 2; i <= x / i; i++) {
        for (; x % i == 0; x /= i) {
            a[++cnt] = i;
        }
    }
    if (x > 1) a[++cnt] = x;
    for (int i = 1; i <= cnt; i++, tot[Cnt]++) { // tot记录对应质数的次数
        if (a[i] != a[i - 1]) pri[++Cnt] = a[i]; // pri记录m1中出现的质数
    }
    return Cnt;
}

int main() {
    scanf("%d%d%d", &n, &m1, &m2);
    int cnt = Decomposition(m1), ans = 2e9, s;
    while (n--) {
        scanf("%d", &s);
        int x = 0;
        for (int i = 1; i <= cnt; i++) {
            int p = pri[i];
            if (s % p != 0) { // 说明这个数没有p这个质因子, 不符合要求
                x = -1;
                break;
            } else {
                int e = 0;
                for (; s % p == 0; s /= p) {
                    e++; // 统计这个质因子出现了几次
                }
                x = max(x, 1 + (m2 * tot[i] - 1) / e); // 计算对应的x
            }
        }
        if (x >= 0) ans = min(ans, x); // 注意: x = 0是可行的
    }
    if (ans >= 2e9) puts("-1");
    else printf("%d", ans);
    return 0;
} 初步学习完结撒花！ 系列导航 ← 02 算法篇 04 HOT 100（前 50） →

