                       res.append([nums[i], nums[j], nums[k]])
                       return res 42 接雨水 十分有名的字节面试题 根本的一个直觉观察是： 一个位置的水量，取决于它左边的墙最高高度、和右边的墙最高高度，二者的最小值。 所谓“短板效应”，看图就能想到了。 因此，要么用动态规划一次性算出所有位置的左边/右边墙最高高度， 要么更进一步优化成双指针、“ 每次计算某个位置的水量时使用最高高度中小的那个 ”： 把这句话反过来就变成了双指针写法！每次取最高高度中小的那个用于计算某个位置中的水量，然后更新小的那一边的最高高度。 还可以更进一步思考： 某个位置中的水量，取决于它自己的高度、和小的那个最高高度。所以只需要每次迭代确定好这两个值就可以了。 方法一： 动态规划 时间复杂度： \(O(n)\) ，空间复杂度： \(O(n)\) class Solution:
    def trap(self, height: List[int]) -> int:
        n = len(height)
        res = 0
        # dp存储每个位置的lmax, rmax
        # 通过从左往右和从右往左两次遍历便捷实现
        lmax, rmax = [0] * n, [0] * n
        lmax[0] = height[0]
        for i in range(1, n):
            lmax[i] = max(height[i], lmax[i - 1])
        rmax[n-1] = height[n-1]
        for i in range(n-2, -1, -1):
            rmax[i] = max(height[i], rmax[i + 1])
        # 根据高度差得到每个位置接的雨水
        for i in range(n):
            min_max = min(lmax[i], rmax[i])
            if min_max > height[i]:
                res += min_max - height[i]
        return res 方法二： 双指针 我们可以从两边往中间收缩计入雨水量。 时间复杂度： \(O(n)\) ，空间复杂度： \(O(1)\) class Solution:
    def trap(self, height: List[int]) -> int:
        if not height:
            return 0

        left, right = 0, len(height) - 1
        left_max = height[left] # 最左边最右边一定没有water
        right_max = height[right]
        water = 0

        while left < right:
            if left_max < right_max: # 双指针: 哪边**最高高度**低, 哪边"决定"水量, 从而"投入使用": 用于计算水量
                left += 1
                # 这里有一点点绕, 其实是两个值用于判断水量,
                # 一个是移动前的left_max (已有的最高墙), 另一个是更新后的height[left] (当前墙高度)。
                left_max = max(left_max, height[left])
                water += left_max - height[left]
            else:
                right -= 1
                right_max = max(right_max, height[right])
                water += right_max - height[right]

        return water 方法三： 单调递减栈 其实这个方法空间复杂度不如双指针。但由于它与 84. 柱状图中最大的矩形 的解法特别对偶，所以顺便补在这里。 我们要找到“ 高低高 ”这样的关系。每次遇到这样的关系，都可以结算栈顶高度（对应“低”），因为找到了低于栈顶高度的两者。 时间复杂度： \(O(n)\) ，空间复杂度： \(O(n)\) def trap(height):
    stack = []  # 存储索引，保持递减
    water = 0

    for i, h in enumerate(height):
        # 当前柱子高于栈顶，形成凹槽
        while stack and height[stack[-1]] < h:
            bottom = stack.pop()  # 凹槽底部
            if not stack:
                break
            left = stack[-1]      # 左边界
            width = i - left - 1
            water += (min(height[left], h) - height[bottom]) * width
        stack.append(i)

    return water 专题三 滑动窗口 3. 无重复字符的最长子串 十分经典的滑动窗口入门题。滑动窗口总是用 右指针用来遍历 新元素、直到不满足某个条件，然后 收缩左指针 直到恰好又满足条件。 时间复杂度： \(O(n)\) ，空间复杂度： \(O(\min \{n, |\Sigma|\})\) 。这是因为 visited 哈希集合中出现的元素数量一定不会超出字符集的数量（如26），同时也不会超出 s 的长度。 class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        visited = set()
        left = 0
        maxLen = 0
        for right, ch in enumerate(s): # 闭区间窗口 [left, right]
            while ch in visited:
                visited.remove(s[left])
                left += 1
            visited.add(ch)
            maxLen = max(maxLen, right - left + 1)
        return maxLen 438. 找到字符串中所有字母异位词 字母异位词通过统计字母频率的方式去做。 方法二： 固定大小滑动窗口+数组统计频率 数组访问是比哈希要快的，两个大小为26的数组相等判断我们也默认它是 \(O(1)\) 的。所以有下述写法。 固定大小的滑动窗口 的写法： 开头添加元素进去。 到达要稳定下来的大小之后，进一个、退一个。 另外还有个python语法，没有什么神秘的，就是字符和ASCII编号的互转：字符转数字用 ord ，数字转字符用 chr 。 时间复杂度： \(O(n)\) ，空间复杂度： \(O(1)\) 。 或者更精细地也可以理解成时间复杂度： \(O(m+(n-m)|\Sigma|)\) ，空间复杂度： \(O(|\Sigma|)\) ，时间复杂度是因为初始化为 \(O(m)\) ，而每次判断为 \(O(|\Sigma|)\) 、需要 \(n-m\) 次判断。其中 \(n\) 和 \(m\) 分别是 s 和 p 的长度，词汇表 \(|\Sigma|=26\) 。 当然，这种方法还可以略微优化：把统计频率改成统计 diff 。这里就不写了。 class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        p_freq, w_freq = [0] * 26, [0] * 26
