class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        heap = []
        for i, node in enumerate(lists):
            if node:
                heapq.heappush(heap, (node.val, i, node)) # 多存一个i是为了避免比较时比较到node
        dummy = ListNode()
        cur = dummy
        while heap:
            val, i, node = heapq.heappop(heap)
            cur.next = node
            cur = cur.next
            if node.next:
                heapq.heappush(heap, (node.next.val, i, node.next))
        return dummy.next 接下来顺便补充一下 手写堆 的写法，以及使用手写堆的解法。 注意这里手写堆的 (n - 1) // 2 和 2 * n + 1 、 2 * n + 2 与数据结构课程讲述的有所不同，但是只要通过下标去推理一下（例如想象一个三个节点的完全二叉树，它的下标分别是0、1、2），可以很快地推出相同的数学关系。 另外注意要根据我们的需要自定义 compare 函数，这里我们需要最小堆、按照原始节点的 val 值（第0个元素）进行比较。 # Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class MinHeap:
    def __init__(self):
        self.heap = []

    def push(self, node):
        """插入节点，上浮调整"""
        self.heap.append(node)
        self._sift_up(len(self.heap) - 1)

    def pop(self):
        """弹出最小节点，下沉调整"""
        if not self.heap:
            return None
        if len(self.heap) == 1:
            return self.heap.pop()

        # 交换堆顶和最后一个元素
        self._swap(0, len(self.heap) - 1)
        min_node = self.heap.pop()
        self._sift_down(0)
        return min_node

    def _sift_up(self, idx):
        """上浮：用于 push"""
        parent = (idx - 1) // 2
        while idx > 0 and self._compare(idx, parent):
            self._swap(idx, parent)
            idx = parent
            parent = (idx - 1) // 2

    def _sift_down(self, idx):
        """下沉：用于 pop"""
        n = len(self.heap)
        while True:
            left = 2 * idx + 1
            right = 2 * idx + 2
            smallest = idx

            if left < n and self._compare(left, smallest):
                smallest = left
            if right < n and self._compare(right, smallest):
                smallest = right

            if smallest == idx:
                break

            self._swap(idx, smallest)
            idx = smallest

    def _compare(self, i, j):
        """比较两个节点，返回 i 是否小于 j"""
        # 按 val 比较，val 相同比较 idx（避免比较 ListNode）
        return self.heap[i][0] < self.heap[j][0]

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def __len__(self):
        return len(self.heap)

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        heap = MinHeap()

        # 初始化堆
        for idx, node in enumerate(lists):
            if node:
                heap.push((node.val, idx, node))  # 用 (值, 索引, 节点) 元组

        dummy = ListNode(0)
        curr = dummy

        while len(heap) > 0:
            val, idx, node = heap.pop()
            curr.next = node
            curr = curr.next

            if node.next:
                heap.push((node.next.val, idx, node.next))

        return dummy.next 解法一： 分治 搞一个合并两个升序链表，然后归并。 时间复杂度： \(O(nK \log K)\) ，空间复杂度： \(O(\log K)\) 其中时间复杂度的 \(n\) 是链表的平均长度。也可以设所有节点总个数为 \(N\) 写为 \(O(N \log K)\) 。 空间复杂度是因为分治的递归栈取决于树的深度，而我们这个分治方法的树是完全二叉树，比较平衡。 # Definition for singly-linked list.
# class ListNode:
