#         self.val = val
#         self.next = next
class Solution:
    def merge2Lists(self, list1, list2):
        dummy = ListNode()
        cur = dummy
        while list1 and list2:
            if list1.val <= list2.val:
                node = list1
                list1 = list1.next
                node.next = None
                cur.next = node
            else:
                node = list2
                list2 = list2.next
                node.next = None
                cur.next = node
            cur = cur.next
        if list1:
            cur.next = list1
        else:
            cur.next = list2
        return dummy.next

    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        if len(lists) == 0:
            return None
        elif len(lists) == 1:
            return lists[0]
        elif len(lists) == 2:
            return self.merge2Lists(lists[0], lists[1])
        else:
            list1 = self.mergeKLists(lists[:int(len(lists) / 2)])
            list2 = self.mergeKLists(lists[int(len(lists) / 2):])
            return self.merge2Lists(list1, list2) 146. LRU 缓存 这个题目用于学习 collections.OrderedDict 的语法。这个结构在算法里常常用到： 我们需要把 dict 和 双向链表 这两个功能结合起来。这样又方便插入删除（从中间取出节点之类的）、又可以快速查找。有下述两个API： move_to_end(key, last=True) 用于把某个元素移动到末尾。 popitem(last=False) 用于删除在开头的元素。 有些同学可能跟我一样常常分不清哪里是last和front。 可以试着直觉上想象一个“小火车”，所以front就是“车头”。 我自己更习惯于想：它总是按照内存顺序直觉上“从左往右排列”的，所以车头就朝向“右边”。 至于这道题，保证 move_to_end 和 popitem 用的 last 变量反过来就好啦。 class LRUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False) 专题八 二叉树 94 二叉树的中序遍历 # Definition for a binary tree node.
