#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def diameterOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        # 转化为经过的节点数
        self.ans = 1
        def depth(node):
            if not node:
                return 0

            l = depth(node.left)
            r = depth(node.right)
            self.ans = max(self.ans, l + r + 1)
            return max(l, r) + 1

        depth(root)
        return self.ans - 1 # 转化回长度 102. 二叉树的层序遍历 我们可以通过记录层数，按照层数构造结果列表； 也可以每次都处理完当前层的所有节点，整成一个列表、添加到结果中。 时间复杂度： \(O(n)\) ，空间复杂度： \(O(n)\) （极端情况下层数可以与节点数相同） # Definition for a binary tree node.
