class Codec:

    def serialize(self, root):
        """Encodes a tree to a single string."""
        def dfs(node):
            if not node:
                return '#,'
            return str(node.val) + ',' + dfs(node.left) + dfs(node.right)
        return dfs(root)

    def deserialize(self, data):
        """Decodes your encoded data to tree."""
        vals = data.split(',')
        self.idx = 0
        def dfs():
            if vals[self.idx] == '#':
                self.idx += 1
                return None
            root = TreeNode(int(vals[self.idx])) # 根左右
            self.idx += 1
            root.left = dfs()
            root.right = dfs()
            return root
        return dfs()


