    def permute(self, nums: List[int]) -> List[List[int]]:
        res = []

        # 回溯: 结束, 遍历, 选择
        def backtrack(path, used):
            if len(path) == len(nums):
                res.append(path[:])
            for i in range(len(nums)):
                if used[i]:
                    continue

                path.append(nums[i])
                used[i] = True
                backtrack(path, used)
                path.pop()
                used[i] = False

        backtrack([], [False] * len(nums))
        return res 78 子集 回溯需要考虑当前start时可以做哪些选择。 class Solution:
