    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        res = []

        def backtrack(path, cur, start):
            if cur == 0:
                res.append(path[:])
                return

            for i in range(start, len(candidates)):
                if candidates[i] > cur:
                    continue
                path.append(candidates[i])
                backtrack(path, cur - candidates[i], i) # 细节: 可以重复使用, 所以是i
                path.pop()

        candidates.sort() # 排序优化剪枝
        backtrack([], target, 0)
        return res 变式：组合总和II （集合中每个元素只能重复使用一次，不同位置可能有相同元素） 关键：只能使用一次通过传入i+1实现，不同位置可能有相同元素通过排序后连续元素剪枝实现。 class Solution:
    def combinationSum2(self, candidates: List[int], target: int) -> List[List[int]]:
        res = []
        def backtrack(path, start, remaining):
            if remaining == 0:
                res.append(path[:])
                return

            for i in range(start, len(candidates)):
                if candidates[i] > remaining: # 剪枝
                    return
                if i > start and candidates[i] == candidates[i - 1]:
                    continue
                path.append(candidates[i])
                backtrack(path, i + 1, remaining - candidates[i]) # 细节: i + 1
                path.pop()

        candidates.sort()
        backtrack([], 0, target)
        return res 22 括号生成 回溯选择：如果左括号数量不到n，则可以加左括号；如果右括号数量少于左括号（当然也不到n），则可以加右括号。 class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        res = []

        def backtrack(path, left, right):
            if len(path) == 2 * n:
                res.append(''.join(path))
            # 可以加左括号的条件
            if left < n:
                path.append('(')
                backtrack(path, left + 1, right)
                path.pop()

            # 可以加右括号的条件: 右括号数量小于左括号数量
            if right < left:
                path.append(')')
                backtrack(path, left, right + 1)
                path.pop()

        backtrack([], 0, 0)
        return res 79. 单词搜索 对于单词搜索问题，我们需要以整个棋盘的每个点为起点，搜索所有可能的路径（如DFS）。 为了剪枝不可行的路径（下述好几处提前返回都起到剪枝的作用），我们需要维护 visited 数组。我们利用相应位置的特殊字符来变相维护 visited 数组。但是， 由于节点需要重复使用，我们需要“回溯”：在标记 visited 之前保存原状态，用完之后恢复原状态。 这道题最有趣的是考虑复杂度。 时间复杂度： \(O(m \times n \times 3^L)\) ，其中 \(m\) 和 \(n\) 是二维网格 board 的行数和列数， \(L\) 是 word 的长度。这是因为，我们需要以每个点为起点，而在搜索过程中由于剪枝，来的方向一定此时已经被标记为 # 了，所以实际上只有3个方向可选。这是一个很宽松的上界。 空间复杂度： \(O(L)\) ，因为我们省去了额外开 visited 数组，但是递归栈的深度取决于 word 的长度。 class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        DIR = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        m, n = len(board), len(board[0])

        def dfs(x, y, cur):
            if board[x][y] != word[cur]:
                return False
            if cur == len(word) - 1:
                return True
            tmp = board[x][y]                     # 这三行是visited数组的逻辑
            board[x][y] = '#'                     # 最重要!
            for dx, dy in DIR:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    if dfs(nx, ny, cur + 1):
                        return True
            board[x][y] = tmp                     # 一定要记得回溯 (前保存, 后恢复) 哦
            return False

        for i in range(m):
            for j in range(n):
                if dfs(i, j, 0):
                    return True
        return False 131 分割回文串 class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res = []
        def backtrack(start, path):
            if start == len(s):
                res.append(path[:])

            for end in range(start, len(s)):
                subs = s[start:end + 1]
                if subs[::-1] == subs:
                    path.append(subs)
                    backtrack(end + 1, path)
                    path.pop()
        backtrack(0, [])
        return res 51 N皇后 仍然是回溯的结束条件、遍历选择空间、做出选择的三步走。 对于N皇后问题，为了简化，我们用回溯函数代表处理特定行（此时排除掉了各行重复的问题），然后对于该函数，遍历所有列作为可能的选择，通过cols、diag1和diag2三个集合作为排除选择的条件。 N皇后的行条件自动保证，列条件有n个（通过col是否存在确定），主对角线有2n-1个（row - col的取值范围是从-(n-1)到(n-1)），副对角线有2n-1个（row + col的取值范围是从2到2n）。通过set是否存在即可。 class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        res = []
        board = [['.'] * n for _ in range(n)]
        cols = set()
        diag1 = set()
        diag2 = set()

        def backtrack(row):
            if row == n:
                res.append([''.join(board_row) for board_row in board])
                return
            for col in range(n):
                if col in cols or (row - col) in diag1 or (row + col) in diag2:
                    continue
                # 做选择
                board[row][col] = 'Q'
                cols.add(col)
                diag1.add(row - col)
                diag2.add(row + col)
                backtrack(row + 1)
                board[row][col] = '.'
                cols.remove(col)
                diag1.remove(row - col)
                diag2.remove(row + col)

        backtrack(0)
