                dp[i][j] = min(dp[i + 1][j], dp[i][j + 1]) + grid[i][j]
        return dp[0][0] 5 最长回文子串 很干净的子串遍历和自底向下填表格问题，值得记忆。 记得像Dijkstra说的那样，左闭右开。 顺手推一下循环上界： (1) 我们使用的字符子串是 s[i:i+length] ，所以有 i + length <= n 得到内层 i < n - length + 1。 (2) 最大的子串应为 s[0:n]，此时i = 0，length = n，所以有外层 length < n + 1。 class Solution:
    def longestPalindrome(self, s: str) -> str:
        n = len(s)
        if n == 1:
            return s

        # dp[i][j]表示s[i:j+1]是否回文
        dp = [[False] * n for _ in range(n)]
        start = 0 # 用于返回解
        maxlen = 1

        for i in range(n):
            dp[i][i] = True

        # 字符串是s[i:i+length]
        # 字符串最后一个字符是s[i + length - 1]
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    if length == 2:
                        dp[i][j] = True
                    else:
                        dp[i][j] = dp[i+1][j-1]
                    if dp[i][j] and length > maxlen:
                        maxlen = length
                        start = i
        return s[start:start + maxlen] 1143 最长公共子序列 皮一下，内层只写一行。 除了转移逻辑，记得处理一下边界。这里字符串下标使用实际下标，但dp使用下标+1，处理边界。 class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        # i是s1的结束位置, j是s2的结束位置
        m, n = len(text1), len(text2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                dp[i][j] = dp[i - 1][j - 1] + 1 if text1[i - 1] == text2[j - 1] else max(dp[i - 1][j], dp[i][j - 1])
        return dp[m][n] 72. 编辑距离 方法二： 滚动数组优化空间 这玩意一口气依赖了三个元素（事实上是对角线形式的依赖），但是仍然可以用滚动数组优化空间复杂度。 其关键是找到并维护好这些关系： 用一个 prev 变量存储 [i - 1][j - 1] 位置的元素。 dp[i][j - 1] 元素当前的存储是 dp[j - 1] 。 dp[i - 1][j] 元素当前的存储是 dp[j] 。 为了维护： 在设置 dp[j] 的值之前，需要把 dp[j] 的值保存下来（相当于 dp[i - 1][j - 1] ）。 （想一下二维数组就好想了） dp[i][0] 直接保存给 prev ，再设置 dp[i][0] 的值为 i ； 在循环中因为 prev 要使用，所以保存给 tmp ，等用完 prev 了再传给它。 时间复杂度： \(O(mn)\) ，空间复杂度： \(O(n)\) class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        # 关键: 使用右边界, 所以需要多开一个, 而且判断时需要用-1
        m, n = len(word1), len(word2)
        # dp[i][j] 代表将word1[:i]转化成word2[:j]的最小操作数
        dp = [j for j in range(n + 1)]

        for i in range(1, m + 1):
            prev = dp[0]
            dp[0] = i # 用来存储当前行的dp初值
            for j in range(1, n + 1):
                tmp = dp[j]
                if word1[i - 1] == word2[j - 1]:
                    dp[j] = prev
                else:
                    dp[j] = 1 + min(dp[j], dp[j - 1], prev)
                prev = tmp
        return dp[n] 方法一： 朴素动态规划 不要被题目吓到。其实就是最长公共子序列那种感觉。题目的三种方式只是三种转移。 十分经典的题目，从CS61A的练习题里就出现过。 时间复杂度： \(O(mn)\) ，空间复杂度： \(O(mn)\) class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        # 关键: 使用右边界, 所以需要多开一个, 而且判断时需要用-1
        m, n = len(word1), len(word2)
        # dp[i][j] 代表将word1[:i]转化成word2[:j]的最小操作数
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            dp[i][0] = i
        for j in range(n + 1):
            dp[0][j] = j
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
        return dp[m][n] 312. 戳气球 十分经典的一道题目，其关键是把戳气球问题，转化为 开区间 (i, j) 的遍历问题 。 对于开区间 (i, j) ， dp[i][j] 表示这一段区间里戳气球能够得到的最大得分。 拆成最优子问题，即以 \(k \in (i, j)\) 为划分点，左右两段的最大得分、加上当前划分点对应的得分。 区间遍历的写法：最外层遍历长度、内层循环遍历起始点。 时间复杂度： \(O(n^3)\) 。空间复杂度： \(O(n^2)\) 。 class Solution:
    def maxCoins(self, nums: List[int]) -> int:
        points = [1] + nums + [1]
        n = len(points)
        dp = [[0] * n for _ in range(n)]
        for length in range(2, n): # 开区间 (i, j)
            for i in range(0, n - length):
                j = i + length
                for k in range(i + 1, j):
                    dp[i][j] = max(dp[i][j], points[i] * points[k] * points[j] + dp[i][k] + dp[k][j])
        return dp[0][n - 1] 专题17 技巧 136 只出现一次的数字 把出现偶数次的用异或消除掉。 class Solution:
    def singleNumber(self, nums: List[int]) -> int:
